UPDATE lessons SET title='Year 8, Week 9, Lesson 2: Writing a prediction and inference response', data=json_patch(data,'{"child_mission":"Prediction and inference responses must stay tethered to evidence and mark uncertainty. Strong writers say what clues suggest and what would confirm or overturn the guess.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWrite an inference paragraph with evidence, a prediction, and a falsifier (what would change your mind).\n\nFEEDBACK\nStrong answer: all three parts present; tone cautious.\n\nCHECK\nPredicting wild plot twists with no textual warrant.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nIndependently keep an inference log for three chapters and revise one earlier prediction with new evidence.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Prediction and inference responses must stay tethered to evidence and mark uncertainty. Strong writers say what clues suggest and what would confirm or overturn the guess.","lesson_number":2,"lesson_role":"Writing","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN4-ECA-01"],"parent_notes":"Parent: Marking guidance for the independent task: Independently keep an inference log for three chapters and revise one earlier prediction with new evidence. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using prediction on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Predicting wild plot twists with no textual warrant.. Correction: Strong answer: all three parts present;. Why it helps the audience is stated.\n\nParent: Likely misconception: Predicting wild plot twists with no textual warrant. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating prediction on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with prediction, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about prediction with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for prediction. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for prediction. The other choices miss a key step or use a common mistake.","options":["all three parts present;","Predicting wild plot twists with no textual warrant.","Ignore the words and invent a more exciting event.","Skip the prompt because the first idea sounded good."],"question":"Write an inference paragraph with evidence, a prediction, and a falsifier (what would change your mind). Which response is most accurate?","type":"multiple_choice"},{"correct_index":2,"explanation":"This is the misconception to avoid for prediction; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["all three parts present;","Careful use of inference with clear evidence.","Predicting wild plot twists with no textual warrant.","Prediction and inference responses must stay tethered to evidence and mark uncertainty."],"question":"Which statement is a common mistake when working with prediction?","type":"multiple_choice"},{"correct_index":3,"explanation":"Understanding is shown by new evidence and a named inference, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Repeat the worked example wording with no new evidence.","Predicting wild plot twists with no textual warrant.","Name inference only, without linking it to prediction.","Apply prediction to new material and name the inference used."],"question":"Which response best applies prediction with new evidence?","type":"multiple_choice"},{"correct_index":0,"explanation":"The skill is shown by quoting or pointing to wording that carries prediction. The other choices miss a key step or use a common mistake.","options":["Point to exact words in the sentence that show prediction and say what they do.","Ignore the sentence and invent a more exciting event.","Say the writing is good without naming any words.","Predicting wild plot twists with no textual warrant."],"question":"Read: \"Under the pier, Sam found a locked tin and a dripping map.\" Which choice best uses prediction from this lesson?","type":"multiple_choice"},{"correct_index":1,"explanation":"The correct statement applies the language skill with textual evidence. The other choices miss a key step or use a common mistake.","options":["Name inference without linking it to any words in the text.","Prediction and inference responses must stay tethered to evidence and mark uncertainty.","Predicting wild plot twists with no textual warrant.","Copy a model sentence from another story unchanged."],"question":"Which statement correctly applies the lesson idea about prediction?","type":"multiple_choice"},{"correct_index":2,"explanation":"Start from a specific textual clue, then explain its effect. The other choices miss a key step or use a common mistake.","options":["Copy a model sentence from another story unchanged.","Lengthen the answer with adjectives while keeping the same idea.","Locate precise textual evidence, then explain how language choices shape meaning or effect.","Guess from the title alone with no textual clue."],"question":"In a new text, what should you do first to analyse inference?","type":"multiple_choice"},{"correct_index":2,"explanation":"Repair means fixing meaning or evidence, not padding. The other choices miss a key step or use a common mistake.","options":["Make the answer longer while keeping the same mistake.","Delete the evidence that disagreed with your first guess.","Change the inaccurate idea or missing evidence, not only the length.","Add adjectives without fixing the wrong idea."],"question":"Which revision actually improves meaning for prediction?","type":"multiple_choice"},{"correct_index":1,"explanation":"Accurate transfer needs fresh material with an explained language choice. The other choices miss a key step or use a common mistake.","options":["Predicting wild plot twists with no textual warrant.","Use a fresh sentence or text and explain one precise choice about prediction.","Retype the worked model as the final answer.","Change fonts and claim the work is new."],"question":"Which response shows accurate use of prediction on fresh material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about prediction with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating prediction on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using prediction on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for prediction. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with prediction, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Predicting wild plot twists with no textual warrant.. Correction: Strong answer: all three parts present;. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent task and reflection, with explanations where requested.","review_status":"unreviewed","seed_key":"s4-eng-y8-w09-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA alignment; verify content points before acceptance.","spelling":null,"spelling_focus":null,"stage":"S4","stage_hints":{"accept":["Today you will practise prediction.","Read the mission before you start writing or speaking.","Keep the audience and purpose in mind as you work."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reason with the feedback.","Adjust anything that does not match the evidence."],"learn":["Study how the first demonstration is built.","Point to the wording that carries the meaning.","Then explain the choice without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore the example.","Prefer evidence over wording that merely sounds clever."],"submit":["Check that your response and reason are both present.","Proofread names, sequence and punctuation.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact word or action before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and underline one useful detail.","Say what that detail helps a reader understand.","A vague compliment is weaker than quoted evidence."],"teach2":["Compare a weak attempt with a stronger revision.","Change meaning or accuracy, not only length.","Name the mistake you are repairing."],"teach3":["Choose a fresh topic that still uses the same skill.","Explain one decision in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include an original response and a short reason.","Save work that shows the skill on new content."]},"subject":"English","success_criteria":["I can use prediction with a specific example from this lesson.","I can identify inference and explain why it matters.","I can practise evidence independently on a new prompt.","I can notice uncertainty needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":1,"explanation":"Prediction and inference responses must stay tethered to evidence and mark uncertainty.","options":["A guess with no explanation.","Prediction and inference responses must stay tethered to evidence and mark uncertainty.","A claim unrelated to the text.","An answer copied without understanding."],"question":"Which choice best shows accurate use of this idea about prediction?","type":"multiple_choice"},"example":"WORKED MODEL\nModel: “I infer X may leave because the packed bag and silence at dinner (ch. 3). I would revise if a scene shows the bag is for someone else.”\n\nTRY FIRST\nWrite an inference paragraph with evidence, a prediction, and a falsifier (what would change your mind).\n\nFEEDBACK\nStrong answer: all three parts present; tone cautious.","explain":"Prediction and inference responses must stay tethered to evidence and mark uncertainty. Strong writers say what clues suggest and what would confirm or overturn the guess.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Predicting wild plot twists with no textual warrant. Correct the meaning, not just the appearance.","title":"Understand and model","visual":[{"alt":"Inference response.","caption":"Add falsifier.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Infer</text><text x=\"28\" y=\"78\">from clues</text><text x=\"358\" y=\"42\">Predict</text><text x=\"358\" y=\"78\">next</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which detail matters most.","who":"pip"},{"text":"Name the exact words or actions that carry the meaning before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Model: “I infer X may leave because the packed bag and silence at dinner (ch. 3). I would revise if a scene shows the ba Then write your own attempt.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which detail matters most.\nJuno: Name the exact words or actions that carry the meaning before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Model: “I infer X may leave because the packed bag and silence at dinner (ch. 3). I would revise if a scene shows the ba Then write your own attempt."}}]},{"check":{"correct_index":1,"explanation":"Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader. A supported explanation follows the actual words and purpose of the task. The other choices miss a key step or use a common mistake.","options":["A guess with no explanation.","Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does","A claim unrelated to the text.","An answer copied without understanding."],"question":"Which choice best shows accurate use of this idea about prediction?","type":"multiple_choice"},"example":"WORKED MODEL\nModel: “I infer X may leave because the packed bag and silence at dinner (ch. 3). I would revise if a scene shows the bag is for someone else.” Think about how this word or relationship creates meaning.\n\nTRY FIRST\nUnderline or quote one precise detail in the model and explain its effect.\n\nFEEDBACK\nThe most useful evidence is a specific choice in the example, followed by an explanation of the effect on meaning.","explain":"Make your choice visible: select the exact detail in the model that demonstrates the skill, and describe what it does for a reader.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Saying a choice is good without naming the actual detail does not show understanding. Correct the meaning, not just the appearance.","title":"Explain the evidence","visual":[{"alt":"Cautious tone.","caption":"Log updates.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Evidence</text><text x=\"28\" y=\"78\">bag/silence</text><text x=\"358\" y=\"42\">Revise</text><text x=\"358\" y=\"78\">if contradicted</text></g></svg>"}]},{"check":{"correct_index":3,"explanation":"Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error. A supported explanation follows the actual words and purpose of the task. The other choices miss a key step or use a common mistake.","options":["A claim unrelated to the text.","An answer copied without understanding.","A guess with no explanation.","Use an intentionally incorrect attempt as a comparison."],"question":"Which choice best shows accurate use of this idea about prediction?","type":"multiple_choice"},"example":"WORKED MODEL\nPredicting wild plot twists with no textual warrant. Here is a more productive model: Model: “I infer X may leave because the packed bag and silence at dinner (ch. 3). I would revise if a scene shows the bag is for someone else.”\n\nTRY FIRST\nDescribe why the warned-against approach would weaken your work, then write a corrected version.\n\nFEEDBACK\nStrong answer: all three parts present; tone cautious.","explain":"Use an intentionally incorrect attempt as a comparison. Name its specific error, then show how a revision fixes that error.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"A superficial change in length or appearance does not repair meaning. Predicting wild plot twists with no textual warrant. Correct the meaning, not just the appearance.","title":"Test a misconception"},{"check":{"correct_index":0,"explanation":"Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity. A supported explanation follows the actual words and purpose of the task. The other choices miss a key step or use a common mistake.","options":["Use the method on a new topic, not a reworded copy of the example.","A claim unrelated to the text.","An answer copied without understanding.","A guess with no explanation."],"question":"Which choice best shows accurate use of this idea about prediction?","type":"multiple_choice"},"example":"WORKED MODEL\nPrediction and inference responses must stay tethered to evidence and mark uncertainty. Strong writers say what clues suggest and what would confirm or overturn the guess. Now choose different people, facts or text to show you can transfer the idea.\n\nTRY FIRST\nMake one fresh example demonstrating the skill and explain your main choice.\n\nFEEDBACK\nThe new example should meet the same purpose as the model, but contain original material.","explain":"Use the method on a new topic, not a reworded copy of the example. Review the result for accuracy and reader clarity.\n\nWHY IT MATTERS\nThis helps the learner make decisions based on specific language evidence, rather than guess or copy someone else. Keep the meaning accurate and explain the choice.\n\nHOW TO WORK\nRead the original example and locate the words or actions that support the idea. Before looking at the correction, make your own attempt using the exact question provided. Check your response against the feedback: did you address the same skill and show your reasoning? If a detail is uncertain, identify what would have to be checked. One deliberate, justified revision is more useful than making the answer longer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new content. Correct the meaning, not just the appearance.","title":"Transfer to an independent example"}],"title":"Year 8, Week 9, Lesson 2: Writing a prediction and inference response","unit_number":3,"unit_title":"Novel study 2","week":9,"week_in_unit":1,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nModel: “I infer X may leave because the packed bag and silence at dinner (ch. 3). I would revise if a scene shows the bag is for someone else.”\n\nExplain what makes this example accurate and effective, identifying its specific wording.","worked_visuals":[{"alt":"Inference response.","caption":"Add falsifier.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Infer</text><text x=\"28\" y=\"78\">from clues</text><text x=\"358\" y=\"42\">Predict</text><text x=\"358\" y=\"78\">next</text></g></svg>"},{"alt":"Cautious tone.","caption":"Log updates.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Evidence</text><text x=\"28\" y=\"78\">bag/silence</text><text x=\"358\" y=\"42\">Revise</text><text x=\"358\" y=\"78\">if contradicted</text></g></svg>"}],"year_level":"Year 8"}') WHERE seed_key='s4-eng-y8-w09-l2' AND family_id IS NULL;
